font_css:
:root { --display: "IBM Plex Sans Arabic", "Space Grotesk", sans-serif; --text: "IBM Plex Sans Arabic", "Instrument Sans", system-ui, sans-serif; }
html[lang="ar"] *, html[lang="ar"] *::before, html[lang="ar"] *::after { letter-spacing: 0 !important; }
html[lang="ar"] body { line-height: 1.85; }
html[lang="ar"] h1 { line-height: 1.15; font-weight: 600; }
html[lang="ar"] .feature-title { line-height: 1.35; }
[dir="rtl"] .arrow { transform: scaleX(-1); margin-left: 0; margin-right: 4px; }
[dir="rtl"] .teaching-topics li { padding-left: 0; padding-right: 12px; }
[dir="rtl"] .teaching-topics li::before { left: auto; right: 0; }
[dir="rtl"] .date, [dir="rtl"] .ltr { direction: ltr; unicode-bidi: isolate; }
[dir="rtl"] .ltr-block { display: inline-block; text-align: left; font-family: "Instrument Sans", system-ui, sans-serif; }
